import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In a math contest, {alpha} students explore ordered geometric progressions: for each n with 1 \\le n \\le {alpha}, consider all nondecreasing sequences (a_1 \\le a_2 \\le \\cdots \\le a_n) with positive terms forming a geometric progression of common ratio r \\ge 1, and additionally satisfying the balance condition \\(\\sum_{k=1}^n a_k = \\sum_{k=1}^n \\frac{1}{a_k}\\). Determine all such n (in the range 1 to {alpha}) for which the inequality \\(\\prod_{k=1}^n a_k^{\\,k^2 - {lambda}k} \\ge 1\\) is guaranteed to hold for every valid choice of r. After solving, output the set of all qualified n using exact enumeration in the format: ### The final answer is: $\\boxed{\\{\\text{list all n}\\}}$'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose alpha sufficiently large to avoid trivial cases
# and choose lambda to ensure both passing and failing n exist
while True:
    alpha = rng.randint(6, 40)
    lam = rng.randint(4, alpha)
    # Validity checks (guarantee some n pass and some fail among 2..alpha)
    # With lam in [4, alpha], we have failures for n in [2, lam-2] and passes for n >= lam-1.
    if isinstance(alpha, int) and isinstance(lam, int) and alpha >= 6 and 4 <= lam <= alpha:
        return {'alpha': alpha, 'lambda': lam}

    def verifier(assign):
# Validate assignment
if not isinstance(assign, dict):
    # Invalid container
    return (False, None)
if 'alpha' not in assign or 'lambda' not in assign:
    # Missing keys
    return (False, None)
alpha = assign['alpha']
lam = assign['lambda']
# Domain constraints
if not isinstance(alpha, int) or not isinstance(lam, int):
    return (False, None)
if alpha < 6:
    # Enforce difficulty: sufficiently large bound
    return (False, None)
if lam < 4 or lam > alpha:
    # Enforce difficulty: ensures both passing and failing n in [2, alpha]
    return (False, None)
# Compute the qualifying set using the derived closed-form criterion
# For geometric progressions satisfying sum equality, the exponent of r in the product is
# L = n(n+1)(n-1)/12 * (n+1 - lam). The inequality holds for all r >= 1 iff L >= 0.
qualified = []
for n in range(1, alpha + 1):
    Lnum = n * (n + 1) * (n - 1) * (n + 1 - lam)  # Denominator 12 is positive, so sign from numerator
    if Lnum >= 0:
        qualified.append(n)
# Format the final answer string with exact enumeration
inner = ", ".join(str(x) for x in qualified)
answer = f"### The final answer is: $\\boxed{{\\{{{inner}\\}}}}$"
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

